import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
}

const DAY_MS = 24 * 60 * 60 * 1000;

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function shiftDays(days: number): Date {
  return startOfDay(new Date(Date.now() - days * DAY_MS));
}

const presets = [
  { id: 'today', label: 'Сегодня', days: 0 },
  { id: 'yesterday', label: 'Вчера', days: 1 },
  { id: 'week', label: 'Неделя назад', days: 7 },
];

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const [internal, setInternal] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : internal;

  const select = (next: Date | null) => {
    if (value === undefined) setInternal(next);
    onChange?.(next);
  };

  const isSame = (date: Date) =>
    selected !== null && startOfDay(selected).getTime() === date.getTime();

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => {
          const date = shiftDays(preset.days);
          return (
            <JxChip
              key={preset.id}
              role="button"
              tabIndex={0}
              aria-pressed={isSame(date)}
              active={isSame(date)}
              onClick={() => select(date)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  select(shiftDays(preset.days));
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale={locale} value={selected} onValueChange={select} />
    </div>
  );
}

